window.STORY={"voice":"The Podcaster","profile_id":"fc6fe0bf","scenes":[{"id":"ava","layout":"name","kicker":"ONE DENIAL. FOUR REASONS.","big":"AVA.","sub":"Sydney. Thirty-four.","voice":"This is Ava. Her insurer said no.","hold":3.2,"wash":"paper","index":1,"voice_file":"voice/01-ava.wav","voice_duration":1.877,"voice_start":0.75,"start":0.6,"end":3.8,"duration":3.2},{"id":"no","layout":"lines","kicker":"THE DENIAL","big":"Four reasons.\nThree are wrong.","sub":"The fourth is missing.","evidence":["4 denial reasons","3 contradicted by the file","1 required document missing"],"voice":"The denial gives four reasons. Three are wrong. The fourth is a document that is actually missing.","hold":7.0,"wash":"paper","index":2,"voice_file":"voice/02-no.wav","voice_duration":5.72,"voice_start":3.95,"start":3.8,"end":10.8,"duration":7.0},{"id":"reads","layout":"lines","kicker":"OVERTURN","big":"It reads the policy.\nThe record.\nThe codes.","sub":"","evidence":["policy clauses","clinical records","EOB","procedure codes","live ICD-10","document checklist"],"voice":"OVERTURN reads the policy, the clinical record and the codes — then answers every reason with evidence.","hold":7.0,"wash":"cobalt","index":3,"voice_file":"voice/03-reads.wav","voice_duration":5.212,"voice_start":10.95,"start":10.8,"end":17.8,"duration":7.0},{"id":"loop","layout":"loop","kicker":"THE LOOP","big":"Plan. Reconcile.\nCritique. Re-query.","sub":"","evidence":["World Model: one shared case","H-MEM: prior appeal + insurer pattern","Nemotron: Critic + Advocate"],"voice":"A planner picks the sources. A reconciler reads them. The critic checks every reason against the policy. The advocate tries to break the appeal — and when it does, the reconciler goes back to the source.","hold":10.5,"wash":"paper","index":4,"voice_file":"voice/04-loop.wav","voice_duration":11.603,"voice_start":17.95,"start":17.8,"end":30.003,"duration":12.203},{"id":"clause","layout":"conflict","kicker":"REASON ONE","leftLabel":"THE DENIAL","leftValue":"DENIED","rightLabel":"THE POLICY","rightValue":"COVERED","delta":"POL-4.3","sub":"The clause excludes spinal fusion, not diagnostic MRI.","evidence":["POL-4.3 applies to SPINE-FUSION-001","POL-4.1 covers MRI-LS-001","6+ weeks of conservative therapy"],"stamp":"REBUTTED","stampAt":2.6,"voice":"Reason one: experimental. The clause it cites says it does not apply to diagnostic MRI.","hold":8.0,"wash":"amber","index":5,"voice_file":"voice/05-clause.wav","voice_duration":5.05,"voice_start":30.153,"start":30.003,"end":38.003,"duration":8.0},{"id":"treatment","layout":"conflict","kicker":"REASON TWO","leftLabel":"THE DENIAL","leftValue":"NONE","rightLabel":"THE FILE / WEEKS","rightValue":"12","delta":"PHYSIO","sub":"Twelve sessions. One NSAID trial.","evidence":["12 physiotherapy sessions","20 May – 5 Aug 2026","NSAID trial: 10 Jun 2026","POL-5.1: at least 6 weeks"],"stamp":"REBUTTED","stampAt":3.2,"voice":"Reason two: no conservative treatment. The record shows twelve weeks of physiotherapy and an NSAID trial.","hold":8.0,"wash":"paper","index":6,"voice_file":"voice/06-treatment.wav","voice_duration":6.207,"voice_start":38.153,"start":38.003,"end":46.003,"duration":8.0},{"id":"code","layout":"bigsub","kicker":"REASON THREE","big":"LS-001","sub":"The file's code. Not the contrast code. No prior auth.","evidence":["Denial: MRI-LS-002 / M51.1","File: MRI-LS-001 / M54.5","MRI-LS-001: no prior auth"],"stamp":"REBUTTED","stampAt":3.4,"voice":"Reason three: the wrong code. The denial uses the contrast code; the file uses LS-001, which needs no prior authorisation.","hold":8.0,"wash":"cobalt","index":7,"voice_file":"voice/07-code.wav","voice_duration":6.82,"voice_start":46.153,"start":46.003,"end":54.003,"duration":8.0},{"id":"letter","layout":"honesty","kicker":"REASON FOUR","big":"ONE.","sub":"required letter.","second":"MISSING.","note":"We don't invent it. We tell you exactly what to send.","secondAt":3.6,"evidence":["DOC-003: missing","required by POL-6.4","requested 20 Aug 2026","not fabricated"],"voice":"Reason four: one required letter is missing. We don't invent it. We put it on the checklist and tell you exactly what to send.","hold":9.0,"wash":"red","index":8,"voice_file":"voice/08-letter.wav","voice_duration":7.178,"voice_start":54.153,"start":54.003,"end":63.003,"duration":9.0},{"id":"score","layout":"score","kicker":"THE APPEAL","big":"84","sub":"SOLID. CONDITIONAL.","note":"Send the letter. 100. Ready.","evidence":["remove policy: 84 → 65","remove record: 84 → 65","supply letter: 84 → 100"],"voice":"Eighty-four. Solid. Conditional. Send one letter, and the appeal becomes one hundred.","hold":7.0,"wash":"green","index":9,"voice_file":"voice/09-score.wav","voice_duration":4.557,"voice_start":63.153,"start":63.003,"end":70.003,"duration":7.0},{"id":"mark","layout":"mark","kicker":"","big":"OVERTURN","sub":"The denial, answered with evidence.","sponsors":["ZETARIS","METERLESS","NVIDIA NEMOTRON"],"voice":"OVERTURN. The denial, answered with evidence.","hold":5.0,"wash":"ink","index":10,"voice_file":"voice/10-mark.wav","voice_duration":2.594,"voice_start":70.153,"start":70.003,"end":75.003,"duration":5.0}],"total":76.003};
